from pathlib import Path
rows=[]
for ln in Path('[REDACTED LOCAL PATH]').read_text().splitlines():
    p=ln.split('\\t')
    if len(p)>=4 and p[0]=='chr22':
        rows.append((p[0], int(p[1]), int(p[2]), int(float(p[3]))))
print('rows', len(rows))
# Merge adjacent zero intervals on chr22
zero=[]
for chrom,start,end,val in rows:
    if val==0:
        if zero and zero[-1][0]==chrom and zero[-1][2]==start:
            zero[-1]=(zero[-1][0], zero[-1][1], end)
        else:
            zero.append((chrom,start,end))
